package ubuntusure.dao;
import ubuntusure.config.Database; import ubuntusure.model.Customer; import java.sql.*; import java.time.LocalDate; import java.util.*;
public class CustomerDao {
 public int create(String first,String surname,String nationalId,LocalDate dob,String gender,String phone,String email,String address)throws SQLException{String sql="INSERT INTO customers(first_name,surname,national_id,date_of_birth,gender,phone,email,physical_address) VALUES(?,?,?,?,?,?,?,?)";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){p.setString(1,first);p.setString(2,surname);p.setString(3,nationalId);p.setDate(4,dob==null?null:java.sql.Date.valueOf(dob));p.setString(5,gender);p.setString(6,phone);p.setString(7,email);p.setString(8,address);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getInt(1);}}throw new SQLException("Customer ID was not returned.");}
 public List<Customer> findAll()throws SQLException{List<Customer> list=new ArrayList<>();String sql="SELECT * FROM customers ORDER BY customer_id DESC";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){while(r.next()){java.sql.Date d=r.getDate("date_of_birth");list.add(new Customer(r.getInt("customer_id"),r.getString("first_name"),r.getString("surname"),r.getString("national_id"),d==null?null:d.toLocalDate(),r.getString("gender"),r.getString("phone"),r.getString("email"),r.getString("physical_address")));}}return list;}
}
